const draw = () => {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  // Ship (triangle)
  ctx.save();
  ctx.translate(center.x, center.y);
  ctx.rotate(shipAngle);
  ctx.beginPath();
  ctx.moveTo(0, -shipRadius);
  ctx.lineTo(shipRadius / 2, shipRadius);
  ctx.lineTo(-shipRadius / 2, shipRadius);
  ctx.closePath();
  ctx.fillStyle = '#0ff';
  ctx.fill();
  ctx.restore();
  // Lasers
  ctx.strokeStyle = '#ff0';
  ctx.lineWidth = 2;
  lasers.forEach(l => {
    ctx.beginPath();
    ctx.moveTo(l.x, l.y);
    ctx.lineTo(l.x - Math.cos(l.angle) * 10, l.y - Math.sin(l.angle) * 10);
    ctx.stroke();
  });
  // Asteroids
  ctx.fillStyle = '#f44';
  asteroids.forEach(a => {
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
    ctx.fill();
  });
  // Score
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText('Score: ' + score, 10, 20);
  // Game over overlay
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#fff';
    ctx.textAlign = 'center';
    ctx.font = '32px sans-serif';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2 - 20);
    ctx.font = '24px sans-serif';
    ctx.fillText('Score: ' + score, canvas.width / 2, canvas.height / 2 + 20);
  }
};

input.newString:
const draw = () => {
  // Background gradient
  const bgGrad = ctx.createLinearGradient(0, 0, 0, canvas.height);
  bgGrad.addColorStop(0, '#00102a');
  bgGrad.addColorStop(1, '#000814');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Stars (twinkling)
  ctx.fillStyle = '#fff';
  stars.forEach(s => {
    ctx.globalAlpha = s.alpha;
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.radius, 0, Math.PI * 2);
    ctx.fill();
  });
  ctx.globalAlpha = 1;

  // Ship (triangle with gradient and outline)
  ctx.save();
  ctx.translate(center.x, center.y);
  ctx.rotate(shipAngle);
  const shipGrad = ctx.createRadialGradient(0, 0, shipRadius * 0.2, 0, 0, shipRadius);
  shipGrad.addColorStop(0, '#00ffff');
  shipGrad.addColorStop(1, '#0066ff');
  ctx.fillStyle = shipGrad;
  ctx.strokeStyle = '#fff';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(0, -shipRadius);
  ctx.lineTo(shipRadius / 2, shipRadius);
  ctx.lineTo(-shipRadius / 2, shipRadius);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  ctx.restore();

  // Lasers with glow
  ctx.save();
  ctx.shadowColor = 'rgba(255,255,0,0.8)';
  ctx.shadowBlur = 8;
  ctx.strokeStyle = '#ff0';
  ctx.lineWidth = 2;
  lasers.forEach(l => {
    ctx.beginPath();
    ctx.moveTo(l.x, l.y);
    ctx.lineTo(l.x - Math.cos(l.angle) * 10, l.y - Math.sin(l.angle) * 10);
    ctx.stroke();
  });
  ctx.restore();

  // Asteroids with shading
  asteroids.forEach(a => {
    const grad = ctx.createRadialGradient(a.x, a.y, a.radius * 0.2, a.x, a.y, a.radius);
    grad.addColorStop(0, '#ff7777');
    grad.addColorStop(1, '#aa0000');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
    ctx.fill();
  });

  // Score
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText('Score: ' + score, 10, 20);

  // Game over overlay
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#fff';
    ctx.textAlign = 'center';
    ctx.font = '32px sans-serif';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2 - 20);
    ctx.font = '24px sans-serif';
    ctx.fillText('Score: ' + score, canvas.width / 2, canvas.height / 2 + 20);
  }
};

